(() => {
  const banks = [
    window.introductionQuestions,
    window.generalQuestions,
    window.limitationsQuestions,
    window.emergencyQuestions,
    window.aircraftSystemsQuestions,
    window.handlingMaintenanceQuestions,
    window.performanceQuestions,
    window.safetyQuestions,
    window.supplementsQuestions,
    window.weightAndBalanceQuestions,
    window.normalOperatingProceduresQuestions
  ];

  for (const bank of banks) {
    if (!Array.isArray(bank)) continue;
    for (const question of bank) {
      const translation = window.questionTranslationsPt[question.factId];
      if (!translation) continue;
      question.questionPt = translation.question;
      question.answersPt = (question.answers || []).map((answer, index) =>
        translation.answers?.[index] || answer
      );
      question.explanationPt = translation.explanation;
    }
  }
})();
